const b=($json.body&&typeof $json.body==='object')?$json.body:{};
const user=String(b.user_id||'').trim(), channel=String(b.channel_id||'').trim();
let text=String(b.content||'').trim();
const allowedUsers=['REPLACE_DISCORD_USER_ID'];
const allowedChannels=['REPLACE_DISCORD_CHANNEL_ID'];
const authorized=b.relay_version==='1'&&allowedUsers.includes(user)&&allowedChannels.includes(channel)&&b.bot!==true;
let action=null;
if(authorized&&text.startsWith('!action ')){
  try{action=JSON.parse(text.slice(8).trim());}catch{throw new Error('Invalid !action JSON');}
  if(!action||typeof action!=='object'||!action.type||!action.payload)throw new Error('!action must contain action type and payload');
  text=`Operator requested approved action ${action.type}`;
}
const rawId=String(b.message_id||Date.now());
const request_id=`discord_${rawId.replace(/[^A-Za-z0-9._:-]/g,'_')}`;
return[{json:{authorized,user,channel,text,action,request_id,source:'discord-relay'}}];

const r=$json; const src=$('Normalize Discord Relay').item.json;
let text='';
if(r.status==='approval_required') text=`Approval required for ${r.request_id||src.request_id}\n${r.approval_url||''}`;
else text=r.summary_markdown||r.answer_markdown||r.draft||r.message||JSON.stringify(r);
if(text.length>1900) text=text.slice(0,1890)+'…';
return[{json:{channel:src.channel,text,response:r}}];
